head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > cellStatusIconPosition]<br/>값이 변경된 Cell 에 표시될 아이콘의 위치를 설정합니다.",
    "validation" : [
        "DataList 모듈의 useCellStatus 속성값이 true 이고, cellStatusVisible=true 인 경우에 동작합니다.",
        "미설정 또는 right 설정 시 값이 변경된 Cell 의 오른쪽 상단에 아이콘을 표시합니다.",
        "left 설정 시 값이 변경된 Cell 의 왼쪽 상단에 아이콘을 표시합니다.",
        "'삽입', '삭제', '삽입 후 삭제' 된 Row 의 전체 Cell 과 값이 '갱신' 된 Cell 에 아이콘이 표시됩니다.",
        "Row 의 상태값에 따라 Cell 에 표시되는 아이콘의 색이 다르게 표시됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }     

    // 조건 설정       
    let properties = {
        cellStatusVisible: true,
        rowStatusVisible: true,
        cellStatusIconPosition: con_cellStatusIconPosition.getText(),
        dataList: "data:dlt_bind",
    };

    let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);       

    // dataList 생성
    $c.gcm.createBasicDataList('useCellStatus="true"', '', 'dlt_bind');

    // target 생성
    $c.gcm.createBasicGridView(cList);

    scwin.btn_insertRow_onclick();
    scwin.btn_deleteRow_onclick();
    scwin.btn_setCellData_onclick();
    // scwin.btn_removeRow_onclick();

    scwin.btn_cellStatusIcon_onclick();
}   



scwin.btn_insertRow_onclick = function (e) {
    let insertIndex = dlt_bind.insertRow();
    dlt_bind.setRowData(insertIndex,["insert1","insert2","insert3","insert4"],true);

    insertIndex = dlt_bind.insertRow();
    dlt_bind.setRowData(insertIndex,["insert5","insert6","insert7","insert8"],true);

    dlt_bind.deleteRow(insertIndex);
};



scwin.btn_deleteRow_onclick = function (e) {
    dlt_bind.deleteRow(0);
};



scwin.btn_setCellData_onclick = function (e) {
    dlt_bind.setCellData(2, "col1", "change");
};



// scwin.btn_removeRow_onclick = function (e) {
//     dlt_bind.removeRow(3);
// }



scwin.btn_cellStatusIcon_onclick = function (e) {
    const parent = document.querySelector('div[id*="target1"]');

    if (parent) {
        const beforeElements = parent.querySelectorAll('.gridBodyDefault[data-col_id="col1"][class*="w2grid_cellStatus_"][class*="_left"]');
        const afterElements = parent.querySelectorAll('.gridBodyDefault[data-col_id="col1"][class*="w2grid_cellStatus_"][class*="_right"]');

        // ::before (Left) 처리
        beforeElements.forEach((el, index) => {
            const style = window.getComputedStyle(el, '::before');
            const borderValue = style.borderTop;
            wf_body_bottom.getObj("scwin").setReturnValue(`[${index}] position: left,  color: ${borderValue}`)
        });

        // ::after (Right) 처리
        afterElements.forEach((el, index) => {
            const style = window.getComputedStyle(el, '::after');
            const borderValue = style.borderTop;
            wf_body_bottom.getObj("scwin").setReturnValue(`[${index}] position: right,  color: ${borderValue}`)
        });
    }   
};
